{
  "name": "agent-dreams",
  "version": "1.0.5",
  "description": "Cognitive sleep cycle & universal persistent memory for AI agents (OpenCode plugin + MCP server)",
  "type": "module",
  "main": "src/index.ts",
  "module": "src/index.ts",
  "exports": {
    ".": "./src/index.ts",
    "./mcp": "./src/mcp/server.ts"
  },
  "bin": {
    "agent-dreams": "./bin/agent-dreams.js",
    "dreams-mcp": "./bin/agent-dreams.js"
  },
  "files": [
    "bin",
    "src",
    "systemd",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "bun": ">=1.1.0"
  },
  "scripts": {
    "test": "DREAMS_OFFLINE=1 bun test",
    "typecheck": "tsc --noEmit"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/maiteuxzanela/agent-dreams.git"
  },
  "homepage": "https://github.com/maiteuxzanela/agent-dreams#readme",
  "bugs": {
    "url": "https://github.com/maiteuxzanela/agent-dreams/issues"
  },
  "author": "Maiteux Zanela",
  "keywords": [
    "agent-dreams",
    "mcp",
    "memory",
    "ai-agents",
    "persistent-memory",
    "sleep-cycle",
    "opencode",
    "claude-desktop"
  ],
  "license": "MIT",
  "devDependencies": {
    "@types/bun": "^1.4.2",
    "bun-types": "^1.4.2",
    "typescript": "^5.9.0"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.32.1",
    "@opencode-ai/plugin": "^1.18.35",
    "@opencode-ai/sdk": "^1.18.35",
    "zod": "^4.6.7"
  }
}
